using System.Diagnostics;
using System.Text.Json;
using FlaUI.Core.AutomationElements;
using FlaUI.UIA3;
/// <summary>Read-only comparisons against controls captured from the actual WinForms editor.</summary>
public sealed class TradeBlotterNativeParityTests
{
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern IntPtr SetThreadDpiAwarenessContext(IntPtr context);
 [Fact]public void Blotter_tabs_layout_and_read_only_navigation_match_WinForms(){
  SetThreadDpiAwarenessContext(new(-4));var root=Environment.GetEnvironmentVariable("IFM_RUST_REPO_ROOT")!;var output=Environment.GetEnvironmentVariable("IFM_RUST_TEST_ARTIFACTS")!;using var state=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,".artifacts/rust-ui/development-ui-processes.json")));using var process=Process.GetProcessById(state.RootElement.GetProperty("RustProcessId").GetInt32());using var automation=new UIA3Automation();var window=automation.FromHandle(process.MainWindowHandle).AsWindow();window.Focus();if(window.FindFirstDescendant(cf=>cf.ByName("Trade Order Editor")) is null)Wait(window,"Trade Orders").AsButton().Invoke();Wait(window,"Trade Blotter").AsButton().Invoke();Wait(window,"Market Selection");Wait(window,"Broker Trade");Wait(window,"Order Fills");Assert.Null(window.FindFirstDescendant(cf=>cf.ByName("Load Chain")));Assert.Null(window.FindFirstDescendant(cf=>cf.ByName("Refresh Trade")));
  Wait(window,"Emulator");Thread.Sleep(500);using(var native=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"trade-control-geometry.json"))))using(var source=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"blotter-winforms-parent.json")))){
   var controls=native.RootElement.GetProperty("controls");var scale=native.RootElement.GetProperty("pixelsPerPoint").GetDouble();var origin=controls.GetProperty("blotter-client");var sourceControls=source.RootElement.GetProperty("Controls").EnumerateArray().ToArray();var sourceOrigin=sourceControls.Single(x=>x.GetProperty("Id").GetString()=="threeTabTradeBlotterLayout");var differences=new List<object>();
   foreach(var id in new[]{"tradeStrategyValue","tradeTypeValue","brokerModeValue"}){var key=id=="tradeStrategyValue"?"Trade Strategy:":id=="tradeTypeValue"?"Trade Type:":"Broker Mode:";var actual=controls.GetProperty(key);var expected=sourceControls.Single(x=>x.GetProperty("Id").GetString()==id);var delta=new[]{(actual[0].GetDouble()-origin[0].GetDouble())*scale-expected.GetProperty("X").GetDouble()+sourceOrigin.GetProperty("X").GetDouble(),(actual[1].GetDouble()-origin[1].GetDouble())*scale-expected.GetProperty("Y").GetDouble()+sourceOrigin.GetProperty("Y").GetDouble(),actual[2].GetDouble()*scale-expected.GetProperty("Width").GetDouble(),actual[3].GetDouble()*scale-expected.GetProperty("Height").GetDouble()};differences.Add(new{id,delta});foreach(var difference in delta)Assert.InRange(Math.Abs(difference),0,3);}
   File.WriteAllText(Path.Combine(output,"blotter-header-parity.json"),JsonSerializer.Serialize(differences,new JsonSerializerOptions{WriteIndented=true}));
  }
  foreach(var tab in new[]{"Market Selection","Broker Trade","Order Fills"}){Wait(window,tab).AsButton().Invoke();Thread.Sleep(750);if(tab=="Market Selection")CompareBroker(output,tab);if(tab=="Broker Trade"){Wait(window,"Contracts:");Wait(window,"OrderPrice:");Wait(window,"Place Order");Wait(window,"Manage qualification...");CompareBroker(output,tab);}if(tab=="Order Fills"){Wait(window,"ORDERS / FILLS");Wait(window,"Update Order Price");Wait(window,"Cancel Unfilled");}FlaUI.Core.Capturing.Capture.Rectangle(window.BoundingRectangle).ToFile(Path.Combine(output,"blotter-rust-"+tab.Replace(" ","-")+".png"));Assert.True(process.Responding);}
  Wait(window,"Broker Trade").AsButton().Invoke();Wait(window,"Manage qualification...").AsButton().Invoke();Wait(window,"Load test report...");Thread.Sleep(300);CompareQualification(output);Assert.True(process.Responding);FlaUI.Core.Input.Keyboard.Press(FlaUI.Core.WindowsAPI.VirtualKeyShort.ESCAPE);Thread.Sleep(200);

 }
 static void CompareQualification(string output){using var source=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"blotter-winforms-qualification.json")));using var native=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"trade-control-geometry.json")));var p=native.RootElement.GetProperty("pixelsPerPoint").GetDouble();var controls=native.RootElement.GetProperty("controls");var origin=controls.GetProperty("qualificationWindow");Assert.InRange(Math.Abs(origin[2].GetDouble()*p-source.RootElement.GetProperty("Width").GetDouble()),0,3);Assert.InRange(Math.Abs(origin[3].GetDouble()*p-source.RootElement.GetProperty("Height").GetDouble()),0,3);var differences=new List<object>();foreach(var x in source.RootElement.GetProperty("Controls").EnumerateArray()){var id=x.GetProperty("Id").GetString()!;if(!controls.TryGetProperty(id,out var r))continue;var delta=new[]{(r[0].GetDouble()-origin[0].GetDouble())*p-x.GetProperty("X").GetDouble(),(r[1].GetDouble()-origin[1].GetDouble())*p-x.GetProperty("Y").GetDouble(),r[2].GetDouble()*p-x.GetProperty("Width").GetDouble(),r[3].GetDouble()*p-x.GetProperty("Height").GetDouble()};differences.Add(new{id,delta});foreach(var d in delta)Assert.InRange(Math.Abs(d),0,3.01);}Assert.True(differences.Count>=10);File.WriteAllText(Path.Combine(output,"blotter-qualification-control-parity.json"),JsonSerializer.Serialize(differences,new JsonSerializerOptions{WriteIndented=true}));}
 static void CompareBroker(string output,string tab){
  using var actualDocument=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"trade-control-geometry.json")));using var originalDocument=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"blotter-winforms-parent-"+tab.Replace(" ","-")+".json")));var scale=actualDocument.RootElement.GetProperty("pixelsPerPoint").GetDouble();var controls=actualDocument.RootElement.GetProperty("controls");var origin=controls.GetProperty("blotter-client");var original=originalDocument.RootElement.GetProperty("Controls").EnumerateArray().ToArray();var sourceOrigin=original.Single(x=>x.GetProperty("Id").GetString()=="threeTabTradeBlotterLayout");var differences=new List<object>();
  foreach(var item in original){var id=item.GetProperty("Id").GetString()!;if(tab=="Broker Trade"&&!id.StartsWith("brokerPreview")&&!id.StartsWith("manageBroker"))continue;if(!controls.TryGetProperty(id,out var box))continue;var delta=new[]{(box[0].GetDouble()-origin[0].GetDouble())*scale-item.GetProperty("X").GetDouble()+sourceOrigin.GetProperty("X").GetDouble(),(box[1].GetDouble()-origin[1].GetDouble())*scale-item.GetProperty("Y").GetDouble()+sourceOrigin.GetProperty("Y").GetDouble(),box[2].GetDouble()*scale-item.GetProperty("Width").GetDouble(),box[3].GetDouble()*scale-item.GetProperty("Height").GetDouble()};differences.Add(new{id,delta});foreach(var difference in delta)Assert.InRange(Math.Abs(difference),0,3.01);}
  File.WriteAllText(Path.Combine(output,"blotter-"+tab.Replace(" ","-")+"-control-parity.json"),JsonSerializer.Serialize(differences,new JsonSerializerOptions{WriteIndented=true}));Assert.True(differences.Count>=(tab=="Broker Trade"?30:7),"Expected the broker fields, leg grid and action controls to be measured");
 }
 static AutomationElement Wait(Window window,string name){var watch=Stopwatch.StartNew();while(watch.Elapsed<TimeSpan.FromSeconds(30)){var item=window.FindFirstDescendant(cf=>cf.ByName(name));if(item is not null && (name!="Trade Blotter" || item.IsEnabled))return item;Thread.Sleep(100);}File.WriteAllLines(Path.Combine(Environment.GetEnvironmentVariable("IFM_RUST_TEST_ARTIFACTS")!,"blotter-native-ui-tree.txt"),window.FindAllDescendants().Select(x=>$"{x.ControlType} | {x.Properties.Name.ValueOrDefault}"));FlaUI.Core.Capturing.Capture.Rectangle(window.BoundingRectangle).ToFile(Path.Combine(Environment.GetEnvironmentVariable("IFM_RUST_TEST_ARTIFACTS")!,"blotter-native-timeout.png"));throw new TimeoutException("Missing "+name);}
}
